        $mode=$input['extractionMode']??null;if($mode==='native_parser')throw new ModelMetadataException('model_native_parser_unavailable');$mode=$this->choice($mode,self::EXTRACTION_MODES,'model_extraction_mode_invalid');
        $fileId=null;$filename='';$sha=null;
