            $statement->execute(['file'=>$fileId,'organisation'=>$organisationId,'project'=>$projectId]);$file=$statement->fetch();if(!is_array($file))throw new ModelMetadataException('model_file_not_found');
            $filename=(string)$file['original_name'];$sha=(string)$file['sha256'];
        }
        if($format==='ifc'&&($fileId===null||strtolower(pathinfo($filename,PATHINFO_EXTENSION))!=='ifc'))throw new ModelMetadataException('model_ifc_file_required');
        $id=Identifier::generate();$values=['id'=>$id,'organisation'=>$organisationId,'project'=>$projectId,'title'=>$this->text($input['title']??null,220,'model_title_required'),'format'=>$format,'schema'=>$this->text($input['schemaVersion']??null,80,'model_schema_required'),'revision'=>$this->text($input['sourceRevision']??null,80,'model_source_revision_required'),'file'=>$fileId,'filename'=>$filename,'sha'=>$sha,'mode'=>$mode,'provider'=>$this->optional($input['providerName']??'',180,'model_provider_invalid'),'assumptions'=>$this->encode($this->strings($input['assumptions']??[])),'role'=>$this->role($input['responsibleRole']??null),'user'=>$userId];
