        return$this->revision($organisationId,$id,$expectedVersion+1);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function decide(string$organisationId,string$userId,string$membershipRole,string$revisionId,array$input):array
    {
        $this->writer($organisationId,$userId,$membershipRole);if(($input['humanConfirmed']??false)!==true)throw new ModelMetadataException('model_decision_confirmation_required');$action=$this->choice($input['action']??null,['approve','reject','flag'],'model_decision_action_invalid');$role=$this->role($input['actingRole']??null);$reason=$this->text($input['reason']??null,500,'model_decision_reason_required');$revisionId=$this->id($revisionId,'model_revision_not_found');
        try{$this->pdo->beginTransaction();$statement=$this->pdo->prepare("SELECT LOWER(HEX(r.source_id)) source_id,LOWER(HEX(r.project_id)) project_id,r.validation_payload,r.status,LOWER(HEX(s.id)) source_check,s.responsible_role,s.status source_status,s.version FROM model_metadata_revisions r JOIN model_sources s ON s.id=r.source_id AND s.organisation_id=r.organisation_id WHERE r.id=UNHEX(:revision) AND r.organisation_id=UNHEX(:organisation) FOR UPDATE");$statement->execute(['revision'=>$revisionId,'organisation'=>$organisationId]);$row=$statement->fetch();if(!is_array($row))throw new ModelMetadataException('model_revision_not_found');if($row['source_status']!=='draft')throw new ModelMetadataException('model_source_issued');if($row['status']==='issued')throw new ModelMetadataException('model_revision_issued');if($role!==$row['responsible_role']||!$this->canActAs($organisationId,$userId,$row['project_id'],$role))throw new ModelMetadataException('model_decision_role_denied');$validation=json_decode((string)$row['validation_payload'],true,64,JSON_THROW_ON_ERROR);if($action==='approve'&&($validation['errors']??[])!==[])throw new ModelMetadataException('model_revision_validation_blocked');
            $decisionId=Identifier::generate();$this->pdo->prepare('INSERT INTO model_metadata_decisions(id,organisation_id,project_id,source_id,revision_id,action,acting_role,reason,decided_by) VALUES(UNHEX(:id),UNHEX(:organisation),UNHEX(:project),UNHEX(:source),UNHEX(:revision),:action,:role,:reason,UNHEX(:user))')->execute(['id'=>$decisionId,'organisation'=>$organisationId,'project'=>$row['project_id'],'source'=>$row['source_id'],'revision'=>$revisionId,'action'=>$action,'role'=>$role,'reason'=>$reason,'user'=>$userId]);$status=$action==='approve'?'approved':($action==='reject'?'rejected':'flagged');
            if($status==='approved'){$this->pdo->prepare("UPDATE model_metadata_revisions SET status='approved',approved_by=UNHEX(:user),approved_role=:role,approved_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:revision) AND organisation_id=UNHEX(:organisation)")->execute(['user'=>$userId,'role'=>$role,'revision'=>$revisionId,'organisation'=>$organisationId]);}else{$this->pdo->prepare('UPDATE model_metadata_revisions SET status=:status,approved_by=NULL,approved_role=NULL,approved_at=NULL WHERE id=UNHEX(:revision) AND organisation_id=UNHEX(:organisation)')->execute(['status'=>$status,'revision'=>$revisionId,'organisation'=>$organisationId]);}
            $this->bump($organisationId,$row['source_id'],(int)$row['version']);(new AuditService($this->pdo))->append($organisationId,$userId,'model.metadata.'.$action,'model_metadata_revision',$revisionId,['sourceId'=>$row['source_id'],'actingRole'=>$role,'reason'=>$reason]);$this->pdo->commit();}catch(Throwable$exception){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$exception;}
        return$this->revision($organisationId,$revisionId,(int)$row['version']+1);
    }

    /** @return array<string,mixed> */
    public function issue(string$organisationId,string$userId,string$membershipRole,string$sourceId,string$revisionId,int$expectedVersion,bool$humanConfirmed,string$professionalRole,string$reason):array
    {
        $this->writer($organisationId,$userId,$membershipRole);if(!$humanConfirmed)throw new ModelMetadataException('model_issue_confirmation_required');$professionalRole=$this->role($professionalRole);$reason=$this->text($reason,500,'model_issue_reason_required');$source=$this->draft($organisationId,$userId,$sourceId,$expectedVersion);if($professionalRole!==$source['responsibleRole']||!$this->canActAs($organisationId,$userId,$source['projectId'],$professionalRole))throw new ModelMetadataException('model_issue_role_denied');$revisionId=$this->id($revisionId,'model_revision_not_found');$revision=null;foreach($source['revisions']as$candidate)if($candidate['id']===$revisionId)$revision=$candidate;if(!is_array($revision)||$revision['status']!=='approved')throw new ModelMetadataException('model_issue_blocked');
        $snapshot=['source'=>['id'=>$source['id'],'projectId'=>$source['projectId'],'title'=>$source['title'],'format'=>$source['format'],'schemaVersion'=>$source['schemaVersion'],'sourceRevision'=>$source['sourceRevision'],'fileId'=>$source['fileId'],'originalFilename'=>$source['originalFilename'],'sourceSha256'=>$source['sourceSha256'],'extractionMode'=>$source['extractionMode'],'providerName'=>$source['providerName'],'assumptions'=>$source['assumptions'],'responsibleRole'=>$source['responsibleRole'],'nativeParsingAvailable'=>false,'externalProviderVerified'=>false],'revision'=>$revision,'professionalConfirmation'=>['confirmed'=>true,'role'=>$professionalRole,'reason'=>$reason,'userId'=>$userId]];$json=$this->encode($snapshot);$sha=hash('sha256',$json);$project=$this->project($organisationId,$source['projectId']);
        try{$this->pdo->beginTransaction();$this->lockDraft($organisationId,$sourceId,$expectedVersion);$recordId=(new ProjectRecordService($this->pdo))->issue(new ProjectContext($organisationId,$userId,$source['projectId'],$membershipRole),ProjectPhase::from($project['currentPhase']),'model_metadata','model_metadata_snapshot',$source['title'].' '.$source['sourceRevision'],'issued',['sourceId'=>$sourceId,'revisionId'=>$revisionId,'snapshotSha256'=>$sha,'snapshot'=>$snapshot],['required'=>true,'professionalConfirmed'=>true,'approvedBy'=>$userId,'actingRole'=>$professionalRole,'reason'=>$reason]);$update=$this->pdo->prepare("UPDATE model_sources SET status='issued',version=version+1,issued_revision_id=UNHEX(:revision),snapshot_sha256=:sha,project_record_id=UNHEX(:record),issue_reason=:reason,issued_by=UNHEX(:user),issued_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:source) AND organisation_id=UNHEX(:organisation) AND version=:version AND status='draft'");$update->execute(['revision'=>$revisionId,'sha'=>$sha,'record'=>$recordId,'reason'=>$reason,'user'=>$userId,'source'=>$sourceId,'organisation'=>$organisationId,'version'=>$expectedVersion]);if($update->rowCount()!==1)throw new ModelMetadataException('model_source_version_conflict');$this->pdo->prepare("UPDATE model_metadata_revisions SET status='issued',issued_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:revision) AND organisation_id=UNHEX(:organisation) AND status='approved'")->execute(['revision'=>$revisionId,'organisation'=>$organisationId]);(new AuditService($this->pdo))->append($organisationId,$userId,'model.metadata.issued','model_source',$sourceId,['revisionId'=>$revisionId,'snapshotSha256'=>$sha,'projectRecordId'=>$recordId,'professionalRole'=>$professionalRole,'nativeParsingAvailable'=>false]);$this->pdo->commit();}catch(Throwable$exception){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$exception;}
        return$this->get($organisationId,$userId,$sourceId);
    }

    /** @return array<string,mixed> */
    public function get(string$organisationId,string$userId,string$sourceId):array
    {
        $this->member($organisationId,$userId);$sourceId=$this->id($sourceId,'model_source_not_found');$statement=$this->pdo->prepare("SELECT LOWER(HEX(s.id)) id,LOWER(HEX(s.project_id)) project_id,s.title,s.source_format,s.schema_version,s.source_revision,LOWER(HEX(s.file_id)) file_id,s.original_filename,s.source_sha256,s.extraction_mode,s.provider_name,s.assumptions,s.responsible_role,s.status,s.version,LOWER(HEX(s.issued_revision_id)) issued_revision_id,s.snapshot_sha256,LOWER(HEX(s.project_record_id)) project_record_id,s.issue_reason,s.issued_at,s.created_at FROM model_sources s WHERE s.id=UNHEX(:source) AND s.organisation_id=UNHEX(:organisation)");$statement->execute(['source'=>$sourceId,'organisation'=>$organisationId]);$row=$statement->fetch();if(!is_array($row))throw new ModelMetadataException('model_source_not_found');
        $revisions=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,revision_number,revision_label,metadata_payload,validation_payload,notes,status,LOWER(HEX(approved_by)) approved_by,approved_role,approved_at,issued_at,created_at FROM model_metadata_revisions WHERE source_id=UNHEX(:source) AND organisation_id=UNHEX(:organisation) ORDER BY revision_number");$revisions->execute(['source'=>$sourceId,'organisation'=>$organisationId]);$items=[];foreach($revisions->fetchAll()as$revision)$items[]=$this->mapRevision($revision,(int)$row['version']);
        $decisions=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(revision_id)) revision_id,action,acting_role,reason,LOWER(HEX(decided_by)) decided_by,created_at FROM model_metadata_decisions WHERE source_id=UNHEX(:source) AND organisation_id=UNHEX(:organisation) ORDER BY created_at,id");$decisions->execute(['source'=>$sourceId,'organisation'=>$organisationId]);$decisionItems=[];foreach($decisions->fetchAll()as$decision)$decisionItems[]=['id'=>$decision['id'],'revisionId'=>$decision['revision_id'],'action'=>$decision['action'],'actingRole'=>$decision['acting_role'],'reason'=>$decision['reason'],'decidedBy'=>$decision['decided_by'],'createdAt'=>$decision['created_at']];
        return['id'=>$row['id'],'projectId'=>$row['project_id'],'title'=>$row['title'],'format'=>$row['source_format'],'schemaVersion'=>$row['schema_version'],'sourceRevision'=>$row['source_revision'],'fileId'=>$row['file_id'],'originalFilename'=>$row['original_filename'],'sourceSha256'=>$row['source_sha256'],'extractionMode'=>$row['extraction_mode'],'providerName'=>$row['provider_name'],'assumptions'=>json_decode((string)$row['assumptions'],true,64,JSON_THROW_ON_ERROR),'responsibleRole'=>$row['responsible_role'],'status'=>$row['status'],'version'=>(int)$row['version'],'issuedRevisionId'=>$row['issued_revision_id'],'snapshotSha256'=>$row['snapshot_sha256'],'projectRecordId'=>$row['project_record_id'],'issueReason'=>$row['issue_reason'],'issuedAt'=>$row['issued_at'],'createdAt'=>$row['created_at'],'revisions'=>$items,'decisions'=>$decisionItems,'nativeParsingAvailable'=>false,'externalProviderVerified'=>false];
    }

    /** @return array<string,mixed> */private function revision(string$o,string$id,int$sourceVersion):array{$statement=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,revision_number,revision_label,metadata_payload,validation_payload,notes,status,LOWER(HEX(approved_by)) approved_by,approved_role,approved_at,issued_at,created_at FROM model_metadata_revisions WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation)");$statement->execute(['id'=>$id,'organisation'=>$o]);$row=$statement->fetch();if(!is_array($row))throw new ModelMetadataException('model_revision_not_found');return$this->mapRevision($row,$sourceVersion);}
    /** @param array<string,mixed> $r @return array<string,mixed> */private function mapRevision(array$r,int$v):array{return['id'=>$r['id'],'revisionNumber'=>(int)$r['revision_number'],'revisionLabel'=>$r['revision_label'],'facts'=>json_decode((string)$r['metadata_payload'],true,64,JSON_THROW_ON_ERROR)['facts'],'validation'=>json_decode((string)$r['validation_payload'],true,64,JSON_THROW_ON_ERROR),'notes'=>$r['notes'],'status'=>$r['status'],'approvedBy'=>$r['approved_by'],'approvedRole'=>$r['approved_role'],'approvedAt'=>$r['approved_at'],'issuedAt'=>$r['issued_at'],'createdAt'=>$r['created_at'],'sourceVersion'=>$v];}
    /** @return array<string,mixed> */private function draft(string$o,string$u,string$id,int$v):array{$source=$this->get($o,$u,$id);if($source['status']==='issued')throw new ModelMetadataException('model_source_issued');if($v<1||$source['version']!==$v)throw new ModelMetadataException('model_source_version_conflict');return$source;}
    /** @return array<string,mixed> */private function lockDraft(string$o,string$id,int$v):array{$statement=$this->pdo->prepare("SELECT s.version,s.status,(SELECT COUNT(*) FROM model_metadata_revisions r WHERE r.source_id=s.id) revision_count FROM model_sources s WHERE s.id=UNHEX(:source) AND s.organisation_id=UNHEX(:organisation) FOR UPDATE");$statement->execute(['source'=>$id,'organisation'=>$o]);$row=$statement->fetch();if(!is_array($row))throw new ModelMetadataException('model_source_not_found');if($row['status']!=='draft')throw new ModelMetadataException('model_source_issued');if((int)$row['version']!==$v)throw new ModelMetadataException('model_source_version_conflict');return$row;}
    private function bump(string$o,string$id,int$v):void{$statement=$this->pdo->prepare("UPDATE model_sources SET version=version+1 WHERE id=UNHEX(:source) AND organisation_id=UNHEX(:organisation) AND version=:version AND status='draft'");$statement->execute(['source'=>$id,'organisation'=>$o,'version'=>$v]);if($statement->rowCount()!==1)throw new ModelMetadataException('model_source_version_conflict');}
    /** @return list<array<string,mixed>> */private function facts(mixed$value):array{if(!is_array($value)||$value===[]||count($value)>2000)throw new ModelMetadataException('model_facts_invalid');$facts=[];foreach($value as$fact){if(!is_array($fact))throw new ModelMetadataException('model_facts_invalid');$facts[]=['category'=>$this->choice($fact['category']??null,self::CATEGORIES,'model_fact_category_invalid'),'externalId'=>$this->optional($fact['externalId']??'',180,'model_fact_external_id_invalid'),'label'=>$this->text($fact['label']??null,220,'model_fact_label_required'),'level'=>$this->optional($fact['level']??'',180,'model_fact_level_invalid'),'value'=>isset($fact['value'])&&$fact['value']!==null?$this->optional((string)$fact['value'],180,'model_fact_value_invalid'):null,'unit'=>$this->optional($fact['unit']??'',40,'model_fact_unit_invalid'),'sourceReference'=>$this->optional($fact['sourceReference']??'',500,'model_fact_source_reference_invalid'),'confidence'=>$this->integer($fact['confidence']??null,0,100,'model_fact_confidence_invalid'),'requiresVerification'=>($fact['requiresVerification']??null)===true];}return$facts;}
    /** @param list<array<string,mixed>> $facts @return array<string,mixed> */private function validateFacts(array$facts):array{$counts=[];$ids=[];$duplicates=[];$missing=[];$verify=[];foreach($facts as$fact){$counts[$fact['category']]=($counts[$fact['category']]??0)+1;if($fact['externalId']!==''){if(isset($ids[$fact['externalId']]))$duplicates[$fact['externalId']]=true;$ids[$fact['externalId']]=true;}if($fact['sourceReference']==='')$missing[]=$fact['externalId']!==''?$fact['externalId']:$fact['label'];if($fact['requiresVerification'])$verify[]=$fact['externalId']!==''?$fact['externalId']:$fact['label'];}ksort($counts);$errors=[];foreach(array_keys($duplicates)as$id)$errors[]='duplicate_external_id:'.$id;sort($errors);sort($missing);sort($verify);return['errors'=>$errors,'warnings'=>$missing===[]?[]:['missing_source_references'],'categoryCounts'=>$counts,'missingSourceReferences'=>array_values(array_unique($missing)),'verificationRequired'=>array_values(array_unique($verify))];}
    /** @return array{currentPhase:string,leadProfessionalRole:string,createdBy:string} */private function project(string$o,string$p):array{$statement=$this->pdo->prepare("SELECT current_phase currentPhase,lead_professional_role leadProfessionalRole,LOWER(HEX(created_by)) createdBy FROM projects WHERE id=UNHEX(:project) AND organisation_id=UNHEX(:organisation)");$statement->execute(['project'=>$p,'organisation'=>$o]);$row=$statement->fetch();if(!is_array($row))throw new ModelMetadataException('model_project_not_found');return$row;}
    private function canActAs(string$o,string$u,string$p,string$r):bool{$project=$this->project($o,$p);if(hash_equals($project['createdBy'],$u)&&$project['leadProfessionalRole']===$r)return true;$statement=$this->pdo->prepare("SELECT 1 FROM project_team_members WHERE organisation_id=UNHEX(:organisation) AND project_id=UNHEX(:project) AND user_id=UNHEX(:user) AND status='active' AND discipline=:role");$statement->execute(['organisation'=>$o,'project'=>$p,'user'=>$u,'role'=>$r]);return$statement->fetchColumn()!==false;}
    private function writer(string$o,string$u,string$r):void{if(!in_array($r,['owner','admin','member'],true))throw new ModelMetadataException('model_permission_denied');$this->member($o,$u);}
    private function member(string$o,string$u):void{$this->id($o,'model_permission_denied');$this->id($u,'model_permission_denied');$statement=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:organisation) AND user_id=UNHEX(:user) AND status='active'");$statement->execute(['organisation'=>$o,'user'=>$u]);if($statement->fetchColumn()===false)throw new ModelMetadataException('model_permission_denied');}
    /** @return list<string> */private function strings(mixed$v):array{if(!is_array($v)||count($v)>50)throw new ModelMetadataException('model_assumptions_invalid');$out=[];foreach($v as$item)$out[]=$this->text($item,500,'model_assumptions_invalid');return$out;}
    private function id(mixed$v,string$e):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new ModelMetadataException($e);return strtolower($v);}
    private function role(mixed$v):string{$v=$this->text($v,80,'model_role_invalid');if(preg_match('/\A[a-z][a-z0-9_]{1,79}\z/',$v)!==1)throw new ModelMetadataException('model_role_invalid');return$v;}
    /** @param list<string> $allowed */private function choice(mixed$v,array$allowed,string$e):string{if(!is_string($v)||!in_array($v,$allowed,true))throw new ModelMetadataException($e);return$v;}
    private function text(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new ModelMetadataException($e);return$v;}
    private function optional(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if(mb_strlen($v)>$m)throw new ModelMetadataException($e);return$v;}
    private function integer(mixed$v,int$min,int$max,string$e):int{if(!is_int($v)||$v<$min||$v>$max)throw new ModelMetadataException($e);return$v;}
